import { scoreArmy } from "./sphinx-score.js";

describe("Sphinx scoring", () => {
  it("scores 0 for an army without a Sphinx — Chimera, Orthrus, Zombie → 0 points", () => {
    expect(
      scoreArmy([
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
      ]),
    ).toBe(0);
  });
  it("scores 2 for a Sphinx with one other type — Sphinx, Cyclops → 2 points", () => {
    expect(scoreArmy([{ monster: "sphinx" }, { monster: "cyclops" }])).toBe(2);
  });
  it("scores 2 for a Sphinx with two other types — Sphinx, Chimera, Orthrus → 2 points", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
      ]),
    ).toBe(2);
  });
  it.todo("counts a monster type only once no matter how many cards — Sphinx, Chimera, Chimera, Chimera, Orthrus, Orthrus → 2 points");
  it.todo("scores 3 when the other cards show four types — Sphinx, Chimera, Orthrus, Zombie, Hydra → 3 points");
  it.todo("scores 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra, Cyclops → 5 points");
  it.todo("lets a Sphinx count another Sphinx but not itself — Sphinx, Sphinx, Chimera, Orthrus → 4 points");
  it.todo("scores each of two Sphinxes beyond three types — Sphinx, Sphinx, Chimera, Orthrus, Zombie → 6 points");
  it.todo("treats all Undead Warrior rank variants as one type — Sphinx, Undead Warrior (1), Undead Warrior (3), Chimera → 2 points");
  it.todo("treats three Undead Warrior variants as one type among four — Sphinx, Undead Warrior (1), Undead Warrior (2), Undead Warrior (3), Cyclops, Orthrus, Chimera → 3 points");
});

